import JSZip from 'jszip'
import { EDITABLE_TABLES, type Tables } from '../schema/tables'
import { serializeTableCsv } from './csv'

// 01_clear は FK 依存の逆順、取り込みは仕様書13章の順
const CLEAR_ORDER = [...EDITABLE_TABLES].reverse()

export function identitySql(): string {
  return [
    '-- 初回のみ実行: エディターが採番したIDを明示投入できるようにする',
    '-- （generated always → generated by default。既存データには影響しない）',
    ...EDITABLE_TABLES.map((t) => `alter table public.${t} alter column id set generated by default;`),
    '',
  ].join('\n')
}

export function clearSql(): string {
  return [
    '-- 取り込み前に実行: エディター管理テーブルを空にする（FK依存の逆順）',
    'begin;',
    ...CLEAR_ORDER.map((t) => `delete from public.${t};`),
    'commit;',
    '',
  ].join('\n')
}

export function afterImportSql(): string {
  return [
    '-- 取り込み後に実行: identityシーケンスを最大IDに合わせる',
    ...EDITABLE_TABLES.map(
      (t) =>
        `select setval(pg_get_serial_sequence('public.${t}', 'id'), coalesce((select max(id) from public.${t}), 0) + 1, false);`,
    ),
    '',
  ].join('\n')
}

export function readme(stamp: string): string {
  return `校内マップ エディター 書き出しデータ (${stamp})

このZIPには、エディターで管理する次の5テーブルの全行が入っています。
  ${EDITABLE_TABLES.join(', ')}
buildings / floors / floorplans / places などの参照テーブルは書き出していません。

■ Supabaseへの反映手順
1. (初回のみ) SQL Editor で 00_once_identity.sql を実行
2. SQL Editor で 01_clear.sql を実行（5テーブルを空にする）
3. Table Editor の「Import data from CSV」で、次の順に取り込む
${EDITABLE_TABLES.map((t, i) => `     ${i + 1}) ${t}.csv`).join('\n')}
4. SQL Editor で 02_after_import.sql を実行（シーケンスを最大IDに合わせる）

※ 2〜3 の間はアプリ側から位置・経路が見えなくなります。
※ 参照テーブル（places 等）を変更した場合は、先にそちらを反映してから取り込んでください。
`
}

export async function buildExportZip(t: Tables): Promise<Blob> {
  const zip = new JSZip()
  const stamp = new Date().toISOString()
  for (const table of EDITABLE_TABLES) zip.file(`${table}.csv`, serializeTableCsv(table, t[table]))
  zip.file('00_once_identity.sql', identitySql())
  zip.file('01_clear.sql', clearSql())
  zip.file('02_after_import.sql', afterImportSql())
  zip.file('README.txt', readme(stamp))
  return zip.generateAsync({ type: 'blob' })
}

export function downloadBlob(blob: Blob, fileName: string) {
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = fileName
  a.click()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}
